import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.jsoup.nodes.Node#siblingIndex()
 */
public class Node_siblingIndex_TriageGen2Test {

    @Test
    public void testSiblingIndex_FirstSibling() {
        Document doc = Document.createShell("");
        Element parent = doc.body();
        Element sibling1 = parent.appendElement("div");
        Element sibling2 = parent.appendElement("span");

        // The first child should have index 0
        Assert.assertEquals(0, sibling1.siblingIndex());
    }

    @Test
    public void testSiblingIndex_MiddleSibling() {
        Document doc = Document.createShell("");
        Element parent = doc.body();
        Element sibling1 = parent.appendElement("div");
        Element sibling2 = parent.appendElement("span");
        Element sibling3 = parent.appendElement("p");

        // The second child should have index 1
        Assert.assertEquals(1, sibling2.siblingIndex());
    }

    @Test
    public void testSiblingIndex_LastSibling() {
        Document doc = Document.createShell("");
        Element parent = doc.body();
        Element sibling1 = parent.appendElement("div");
        Element sibling2 = parent.appendElement("span");

        // The last child should have index 1
        Assert.assertEquals(1, sibling2.siblingIndex());
    }

    @Test
    public void testSiblingIndex_AfterRemoval() {
        Document doc = Document.createShell("");
        Element parent = doc.body();
        Element sibling1 = parent.appendElement("div");
        Element sibling2 = parent.appendElement("span");
        Element sibling3 = parent.appendElement("p");

        // Remove the first sibling
        sibling1.remove();

        // The former second sibling should now be the first sibling (index 0)
        Assert.assertEquals(0, sibling2.siblingIndex());
        // The former third sibling should now be the second sibling (index 1)
        Assert.assertEquals(1, sibling3.siblingIndex());
    }

    @Test
    public void testSiblingIndex_AfterInsertion() {
        Document doc = Document.createShell("");
        Element parent = doc.body();
        Element sibling1 = parent.appendElement("div");
        Element sibling2 = parent.appendElement("p");

        // Insert a new element before sibling2
        Element newSibling = new Element.Tag("span").asElement();
        sibling2.before(newSibling.toString()); 
        // Note: using before(String) to trigger the internal DOM manipulation

        // Re-fetch or rely on the fact that parent now has [div, span, p]
        // Since we used before(String), we need to find the new node
        Element insertedNode = parent.childNode(1);

        Assert.assertEquals(0, sibling1.siblingIndex());
        Assert.assertEquals(1, insertedNode.siblingIndex());
        Assert.assertEquals(2, sibling2.siblingIndex());
    }

    @Test
    public void testSiblingIndex_NoParent() {
        // A node without a parent (root or detached)
        // In Jsoup, if a node has no parent, its sibling index is typically 0 or undefined 
        // depending on internal state, but according to the API it returns the field value.
        Element detached = Element.createElement("div");

        // For a detached node, the sibling index is 0
        Assert.assertEquals(0, detached.siblingIndex());
    }
}
